-- Generated by scripts/build_compiled.py from src/fraudrules/rules/instant-payment/ip-001-instant-in-instant-out.yaml. Do not edit.
-- IP-001 New account sends an instant credit straight back out within minutes
SELECT 'IP-001' AS rule_id, 'transactions' AS anchor_table, a.id AS anchor_id
FROM transactions AS a
JOIN transactions AS b ON b.account_id = a.account_id AND b.ts <= a.ts AND b.ts > a.ts - 1800
WHERE (a.direction = 'out' AND a.channel IN ('rtp', 'fednow', 'p2p') AND a.ts < (a.account_opened_ts + 2592000)) AND (b.direction = 'in' AND b.channel IN ('rtp', 'fednow', 'p2p') AND b.txn_type <> 'return')
GROUP BY a.id
HAVING (SUM(b.amount_cents) >= 100000 AND MAX(a.amount_cents) * 100 >= SUM(b.amount_cents) * 80);
